class Solution {
public:
    bool canReorderDoubled(vector<int>& arr) {
        map<int, int> count;
        for (int x : arr) count[x]++;

        vector<int> keys;
        for (auto& p : count) keys.push_back(p.first);
        sort(keys.begin(), keys.end(), [](int a, int b) {
            return abs(a) < abs(b);
        });

        for (int x : keys) {
            if (count[x] == 0) continue;
            if (count[2 * x] < count[x]) return false;
            count[2 * x] -= count[x];
            count[x] = 0;
        }
        return true;
    }
};
